#!/usr/bin/env sh
# Generated by ~/.config/hypr/shell.lua
# Style: gruvbox-dark-base

# Only apply in interactive terminals.
case "$-" in
  *i*) ;;
  *) return 0 2>/dev/null || exit 0 ;;
esac

# OSC helper. ST terminator is ESC backslash.
osc() { printf '\033]%s\033\\' "$1"; }

# Terminal foreground, background, cursor.
osc '10;#ebdbb2'
osc '11;#282828'
osc '12;#d79921'

# ANSI palette.
osc '4;0;#1d2021'
osc '4;1;#fb4934'
osc '4;2;#b8bb26'
osc '4;3;#fabd2f'
osc '4;4;#458588'
osc '4;5;#d79921'
osc '4;6;#d65d0e'
osc '4;7;#ebdbb2'
osc '4;8;#928374'
osc '4;9;#fb4934'
osc '4;10;#b8bb26'
osc '4;11;#fabd2f'
osc '4;12;#458588'
osc '4;13;#d79921'
osc '4;14;#d65d0e'
osc '4;15;#fbf1c7'

# Optional readline/fzf-ish defaults for tools that honor env colors.
export FZF_DEFAULT_OPTS=${FZF_DEFAULT_OPTS:-'--color=fg:#ebdbb2,bg:#282828,hl:#d79921,fg+:#fbf1c7,bg+:#32302f,hl+:#d65d0e,info:#a89984,prompt:#d79921,pointer:#d65d0e,marker:#b8bb26'}
